import { expect, test } from "bun:test";
import { Database } from "bun:sqlite";
import { createHash } from "node:crypto";
import { decisionMetadata } from "../../agent/decision-metadata";
import { createConsultCaptureStore, type ConsultCaptureStore } from "./capture-store";
import { captureMetadataReference } from "./metadata-reference";

const asset = "token:501:So11111111111111111111111111111111111111112", id = `buy:${asset}`;
const sha = (v: unknown) => createHash("sha256").update(JSON.stringify(v)).digest("hex");
// Synthetic market/source data; metadata is generated by the actual pure
// producer. This is contract compatibility, never a real trade or result.
function fixture() {
  const full = { v: 1, carteira: {}, chaves: {}, posicoes: {}, compras: {}, contexto: {}, historico: {}, mandato: null };
  const consultation = { cycleId: "synthetic-reference", atMs: 1000, mode: "limitado", posture: "ofensiva", briefVersion: 1, briefHash: sha(full).slice(0, 16), brief: { carteira: {}, chaves: {}, posicoes: {}, compras: {}, mandato: null }, contexto: {}, historico: {},
    candidates: [{ id, kind: "buy", stances: ["skip", "buy_full"], marks: [] }], notes: [], valid: true, invalidReason: null, requested: { [id]: "buy_full" }, stances: { [id]: "buy_full" } };
  const metadata = { ...decisionMetadata({ recordLine: JSON.stringify(consultation), snapshotHash: sha(full), decisionVersion: "a".repeat(64), evaluatorHash: "b".repeat(64), factAvailableAtMs: 1100, askedAtMs: 1200, answeredAtMs: 1400, recordedAtMs: 1500 })! };
  return { consultation, reference: { cycleId: consultation.cycleId, atMs: consultation.atMs, metadata } };
}
function setup() { const db = new Database(":memory:"), opened = createConsultCaptureStore(db); if (!opened.ok) throw new Error(opened.code); return { db, store: opened.store }; }

test("actual producer reference resolves only its exact raw hash and preserves distinct availability", () => {
  const { store } = setup(), { consultation, reference } = fixture();
  store.capture("agent_briefs", consultation, 2000); reference.metadata.recordedAtMs = 2500;
  const first = captureMetadataReference(reference, { store, observedAtMs: 3000, arm: "A" });
  expect(first).toMatchObject({ ok: true, status: "bound", local: { referenceFirstObservedAtMs: 3000 }, evidence: { local: { sourceFirstObservedAtMs: 2000, metadataFirstObservedAtMs: 3000 }, experiences: [{ recordedAtMs: 3000, outcome: null }] } });
  expect(captureMetadataReference(reference, { store, observedAtMs: 9000, arm: "A" })).toEqual(first);
});

test("reference retained before source waits honestly and later resolution cannot backdate the derived envelope", () => {
  const { store } = setup(), { consultation, reference } = fixture();
  expect(captureMetadataReference(reference, { store, observedAtMs: 2000, arm: "A" })).toMatchObject({ ok: true, status: "awaiting_source", evidence: null, local: { referenceFirstObservedAtMs: 2000 } });
  store.capture("agent_briefs", consultation, 4000);
  expect(captureMetadataReference(reference, { store, observedAtMs: 5000, arm: "A" })).toMatchObject({ ok: true, status: "bound", local: { referenceFirstObservedAtMs: 2000 }, evidence: { local: { sourceFirstObservedAtMs: 4000, metadataFirstObservedAtMs: 5000 }, experiences: [{ recordedAtMs: 5000 }] } });
});

test("a metadata recording after first reference observation cannot hide behind later resolution", () => {
  const { store } = setup(), { consultation, reference } = fixture(); reference.metadata.recordedAtMs = 2500;
  expect(captureMetadataReference(reference, { store, observedAtMs: 2000, arm: "A" })).toMatchObject({ ok: true, status: "metadata_rejected", evidence: null });
  store.capture("agent_briefs", consultation, 4000);
  expect(captureMetadataReference(reference, { store, observedAtMs: 5000, arm: "A" })).toMatchObject({ ok: true, status: "metadata_rejected", evidence: null, local: { referenceFirstObservedAtMs: 2000 } });
});

test("wrong reference hash is not resolved by a different raw record of the same cycle", () => {
  const { store } = setup(), { consultation, reference } = fixture(); store.capture("agent_briefs", consultation, 2000); reference.metadata.sourceRecordHash = "d".repeat(64);
  expect(captureMetadataReference(reference, { store, observedAtMs: 3000, arm: "A" })).toMatchObject({ ok: true, status: "awaiting_source", evidence: null });
  expect(store.list("agent_decision_evidence", { afterSequence: 0, limit: 10 })).toMatchObject({ ok: true, records: [] });
});

test("reference/source conflicts and atMs disagreement cannot create a usable packet", () => {
  const { store } = setup(), { consultation, reference } = fixture(); store.capture("agent_briefs", consultation, 2000);
  const differentAt = { ...reference, atMs: 999 };
  expect(captureMetadataReference(differentAt, { store, observedAtMs: 3000, arm: "A" })).toMatchObject({ ok: true, status: "quarantined", evidence: null });
  expect(captureMetadataReference(reference, { store, observedAtMs: 4000, arm: "A" })).toMatchObject({ ok: true, status: "quarantined", evidence: null });
});

test("unavailable lookup, rejected shapes, wrong arm and regressive clocks fail without invented data", () => {
  const { store } = setup(), { reference } = fixture();
  const noLookup: ConsultCaptureStore = { capture: store.capture, list: store.list };
  expect(captureMetadataReference(reference, { store: noLookup, observedAtMs: 2000, arm: "A" })).toMatchObject({ ok: false, code: "lookup_unavailable" });
  expect(captureMetadataReference({ ...reference, extra: true }, { store, observedAtMs: 2000, arm: "A" })).toMatchObject({ ok: false, code: "reference_invalid" });
  expect(captureMetadataReference(reference, { store, observedAtMs: 2000, arm: "B" })).toMatchObject({ ok: false, code: "reference_invalid" });
  captureMetadataReference(reference, { store, observedAtMs: 4000, arm: "A" });
  expect(captureMetadataReference(reference, { store, observedAtMs: 3000, arm: "A" })).toMatchObject({ ok: false, code: "observation_invalid" });
});
